using Microsoft.Data.Sqlite; using Workbench.Core.Workers; using Workbench.Storage.Database;
namespace Workbench.Storage.Workers;
public sealed record StoredClarification(Guid Id,Guid ProjectId,Guid TaskId,int Revision,TaskClarificationCategory Category,string Question,string Reason,DateTimeOffset CreatedAt);
public sealed class TaskClarificationRepository(WorkbenchDatabase database){readonly WorkbenchDatabase _d=database;public async Task AddAsync(Guid project,Guid id,TaskClarificationRequest r,string reason,CancellationToken ct=default){await using var c=_d.CreateConnection();await c.OpenAsync(ct);var q=c.CreateCommand();q.CommandText="INSERT INTO task_clarifications(id,task_id,revision_number,category,question_or_conflict,reason,created_at) SELECT $i,$t,$n,$c,$q,$r,$a WHERE EXISTS(SELECT 1 FROM tasks WHERE id=$t AND project_id=$p)";q.Parameters.AddWithValue("$i",id.ToString());q.Parameters.AddWithValue("$p",project.ToString());q.Parameters.AddWithValue("$t",r.TaskId.ToString());q.Parameters.AddWithValue("$n",r.RevisionNumber);q.Parameters.AddWithValue("$c",r.Category.ToString());q.Parameters.AddWithValue("$q",r.QuestionOrConflict);q.Parameters.AddWithValue("$r",reason);q.Parameters.AddWithValue("$a",r.CreatedAt.ToString("O"));await q.ExecuteNonQueryAsync(ct);}public async Task<IReadOnlyList<StoredClarification>> ListAsync(Guid project,Guid task,CancellationToken ct=default){await using var c=_d.CreateConnection();await c.OpenAsync(ct);var q=c.CreateCommand();q.CommandText="SELECT id,$p,task_id,revision_number,category,question_or_conflict,reason,created_at FROM task_clarifications WHERE task_id=$t AND EXISTS(SELECT 1 FROM tasks WHERE id=$t AND project_id=$p) ORDER BY created_at,id";q.Parameters.AddWithValue("$p",project.ToString());q.Parameters.AddWithValue("$t",task.ToString());await using var r=await q.ExecuteReaderAsync(ct);var list=new List<StoredClarification>();while(await r.ReadAsync(ct))list.Add(new(Guid.Parse(r.GetString(0)),project,Guid.Parse(r.GetString(2)),r.GetInt32(3),Enum.Parse<TaskClarificationCategory>(r.GetString(4)),r.GetString(5),r.GetString(6),DateTimeOffset.Parse(r.GetString(7))));return list;}}
